// Some portions generated by Codex
package org.eclipse.rdf4j.query.resultio.binary;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.util.List;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.query.resultio.helpers.QueryResultCollector;
import org.junit.jupiter.api.Test;

class BinaryQueryResultWriterStateTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final List<String> COLUMNS = List.of("value");

	@Test
	void reusedMutableBindingSetDoesNotChangeThePreviousRow() throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		MapBindingSet row = new MapBindingSet();
		row.setBinding("value", VF.createLiteral("first"));

		writer.startQueryResult(COLUMNS);
		writer.handleSolution(row);
		row.setBinding("value", VF.createLiteral("second"));
		writer.handleSolution(row);
		writer.endQueryResult();

		QueryResultCollector collector = parse(output.toByteArray());
		assertEquals(List.of(
				new ListBindingSet(COLUMNS, VF.createLiteral("first")),
				new ListBindingSet(COLUMNS, VF.createLiteral("second"))), collector.getBindingSets());
	}

	@Test
	void reusedWriterDefinesNamespacesInEachIndependentDocument() throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		BindingSet row = new ListBindingSet(COLUMNS, VF.createLiteral("same value"));
		writer.startQueryResult(COLUMNS);
		writer.handleSolution(row);
		writer.endQueryResult();
		byte[] firstDocument = output.toByteArray();

		output.reset();
		writer.startQueryResult(COLUMNS);
		writer.handleSolution(row);
		writer.endQueryResult();
		byte[] secondDocument = output.toByteArray();

		assertArrayEquals(firstDocument, secondDocument);
		// A fresh parser has no namespaces from the preceding document.
		assertEquals(List.of(row), parse(secondDocument).getBindingSets());
	}

	private static QueryResultCollector parse(byte[] bytes) throws Exception {
		QueryResultCollector collector = new QueryResultCollector();
		BinaryQueryResultParser parser = new BinaryQueryResultParser();
		parser.setQueryResultHandler(collector);
		parser.parseQueryResult(new ByteArrayInputStream(bytes));
		return collector;
	}
}
